{
  "status": "SUPPORTED",
  "task_summary": "Derive a functional requirement contract for preparing and serving coffee and soup for two people.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "coffee_cup_role",
        "entity_kind": "OBJECT",
        "function": "Receiving vessel for prepared coffee",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["mug", "cups", "travel mugs", "tea glasses"],
        "required_properties": []
      },
      {
        "id": "soup_bowl_role",
        "entity_kind": "OBJECT",
        "function": "Receiving vessel for served soup",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["bowl", "dinner bowl", "eating dish", "soup tureen"],
        "required_properties": []
      },
      {
        "id": "coffee_ingredient_container",
        "entity_kind": "REGION",
        "function": "Physical storage of coffee granules",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["canister", "jar", "box", "kitchen pantry unit"],
        "required_properties": []
      },
      {
        "id": "water_source_container",
        "entity_kind": "REGION",
        "function": "Physical storage of drinking water",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["bottle", "pitcher", "kettle", "faucet basin", "sink tap"],
        "required_properties": []
      },
      {
        "id": "soup_stock_pot",
        "entity_kind": "REGION",
        "function": "Physical storage of pre-prepared soup",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["stockpot", "large pot", "container", "food warmer"],
        "required_properties": []
      },
      {
        "id": "stirring_utensil_role",
        "entity_kind": "OBJECT",
        "function": "Tool for mixing coffee contents",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["spoon", "whisk", "stick", "stirrer"],
        "required_properties": []
      },
      {
        "id": "soup_eating_utensil_role",
        "entity_kind": "OBJECT",
        "function": "Tool for consuming soup",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["soup spoon", "fork", "knife"],
        "required_properties": []
      }
    ],
    "functional_relations": [
      {
        "id": "rel_coffee_access_ingredients",
        "subject_role": "coffee_cup_role",
        "relation": "requires access to coffee ingredients",
        "object_role": "coffee_ingredient_container",
        "required": true
      },
      {
        "id": "rel_coffee_access_water",
        "subject_role": "coffee_cup_role",
        "relation": "requires access to water source",
        "object_role": "water_source_container",
        "required": true
      },
      {
        "id": "rel_coffee_preparation_tool",
        "subject_role": "stirring_utensil_role",
        "relation": "used to mix contents of",
        "object_role": "coffee_cup_role",
        "required": true
      },
      {
        "id": "rel_soup_transfer_source",
        "subject_role": "soup_stock_pot",
        "relation": "transfers contents to",
        "object_role": "soup_bowl_role",
        "required": true
      },
      {
        "id": "rel_serving_adjacency",
        "subject_role": "soup_eating_utensil_role",
        "relation": "placed adjacent to serving of",
        "object_role": "soup_bowl_role",
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "op_fill_coffee_with_powder",
        "operation": "Transfer dry coffee to cup",
        "source_role": "coffee_ingredient_container",
        "target_role": "coffee_cup_role",
        "operation_count": 2,
        "reuse_policy": "DEDICATED_PER_TARGET",
        "anchor_role": "coffee_cup_role"
      },
      {
        "id": "op_add_water_to_coffee",
        "operation": "Pour water into coffee cup",
        "source_role": "water_source_container",
        "target_role": "coffee_cup_role",
        "operation_count": 2,
        "reuse_policy": "DEDICATED_PER_TARGET",
        "anchor_role": "coffee_cup_role"
      },
      {
        "id": "op_stir_coffee_mixtures",
        "operation": "Stir coffee mixture in cup",
        "source_role": "stirring_utensil_role",
        "target_role": "coffee_cup_role",
        "operation_count": 2,
        "reuse_policy": "REUSABLE_ACROSS_TARGETS",
        "anchor_role": "coffee_cup_role"
      },
      {
        "id": "op_ladle_soup_portions",
        "operation": "Fill soup bowl from stockpot",
        "source_role": "soup_stock_pot",
        "target_role": "soup_bowl_role",
        "operation_count": 2,
        "reuse_policy": "REUSABLE_ACROSS_TARGETS",
        "anchor_role": "soup_bowl_role"
      },
      {
        "id": "op_assign_eating_utensils",
        "operation": "Place eating utensil with soup",
        "source_role": "soup_eating_utensil_role",
        "target_role": "soup_bowl_role",
        "operation_count": 2,
        "reuse_policy": "DEDICATED_PER_TARGET",
        "anchor_role": "soup_bowl_role"
      }
    ]
  },
