      },
      {
        "id": "region_table_drawer_left",
        "label": "Table Drawer Left Side",
        "visual_description": "Grey drawer with white handle attached to the left side of the table.",
        "reason": "Possible hiding place for spare cups, spoons, or other serving ware."
      },
      {
        "id": "region_table_drawer_right",
        "label": "Table Drawer Right Side",
        "visual_description": "Grey drawer with white handle attached to the right side of the table.",
        "reason": "Possible hiding place for additional utensils or serving items."
      }
    ],
    "inspection_order": [
      "region_right_cabinet_storage",
      "region_left_cabinet_storage",
      "region_table_drawer_left",
      "region_table_drawer_right"
